{"path":"/root/solve.py","content":"#!/usr/bin/env python3
import csv
import json
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

ROOT = Path('/root')

SIX_DAY = {'days_per_dispatch': 6, 'dispatches_per_year': 60}
TWELVE_DAY = {'days_per_dispatch': 12, 'dispatches_per_year': 30}
THRESHOLD = Decimal('11000')

CURRENCY_KEYS = {
    'crate_cost_usd',
    'payment_per_dispatch_per_clinic_usd',
    'drug_cost_per_1000_doses_usd',
    'annual_revenue_usd',
    'annual_drug_cost_usd',
    'annual_crate_cost_usd',
    'annual_margin_usd',
    'annual_margin_6_day_usd',
    'annual_margin_12_day_usd',
    'annual_margin_difference_12_minus_6_usd',
    'total_annual_margin_6_day_usd',
    'total_annual_margin_12_day_usd',
    'total_annual_margin_difference_12_minus_6_usd',
    'absolute_total_margin_difference_usd',
    'decision_threshold_usd',
}


def money(value):
    return Decimal(value).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)


def dec(value):
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value).strip())


def load_csv(name):
    with (ROOT / name).open(newline='') as f:
        return list(csv.DictReader(f))


def flatten_campaigns(node):
    """Accept a JSON array of campaigns or an object containing campaigns nested in lists/dicts."""
    campaigns = []
    if isinstance(node, list):
        for item in node:
            campaigns.extend(flatten_campaigns(item))
    elif isinstance(node, dict):
        if 'campaign_id' in node:
            campaigns.append(node)
        else:
            for value in node.values():
                if isinstance(value, (list, dict)):
                    campaigns.extend(flatten_campaigns(value))
    return campaigns


def latest_billing_by_campaign(campaign, billing_rows):
    labels = {campaign.get('campaign_name', '')}
    labels.update(campaign.get('alias_labels') or [])
    matches = [
        row for row in billing_rows
        if row.get('campaign_label') in labels and row.get('status') == 'active'
    ]
    if not matches:
        raise ValueError(f"No active billing row found for {campaign['campaign_id']}")
    return max(matches, key=lambda row: row.get('cycle_tag', ''))


def active_clinics_for_campaign(campaign, override_rows):
    valid = []
    for row in override_rows:
        if row.get('campaign_id') != campaign['campaign_id']:
            continue
        if row.get('state') != 'approved':
            continue
        revision = (row.get('revision') or '').strip()
        active_clinics = (row.get('active_clinics') or '').strip()
        if not revision or not active_clinics:
            continue
        valid.append((int(revision), int(active_clinics)))
    if valid:
        return max(valid, key=lambda item: item[0])[1]
    return int(campaign['default_active_clinics'])


def metric_block(campaign, active_clinics, payment, crate_cost, dispatch_profile):
    days_per_dispatch = Decimal(dispatch_profile['days_per_dispatch'])
    dispatches_per_year = Decimal(dispatch_profile['dispatches_per_year'])
    drug_cost = dec(campaign['drug_cost_per_1000_doses_usd'])
    doses_per_day = Decimal(str(campaign['doses_per_day']))
    clinics = Decimal(active_clinics)

    annual_revenue = payment * clinics * dispatches_per_year
    annual_drug_cost = drug_cost * clinics * doses_per_day * days_per_dispatch * dispatches_per_year / Decimal('1000')
    annual_crate_cost = crate_cost * dispatches_per_year
    annual_margin = annual_revenue - annual_drug_cost - annual_crate_cost

    return {
        'days_per_dispatch': int(days_per_dispatch),
        'dispatches_per_year': int(dispatches_per_year),
        'annual_revenue_usd': money(annual_revenue),
        'annual_drug_cost_usd': money(annual_drug_cost),
        'annual_crate_cost_usd': money(annual_crate_cost),
        'annual_margin_usd': money(annual_margin),
    }


def json_number_dump(obj, indent=2):
    """JSON dump that keeps Decimal currency literals formatted as 2-decimal numbers."""
    def render(value, level):
        pad = ' ' * (indent * level)
        next_pad = ' ' * (indent * (level + 1))
        if isinstance(value, dict):
            if not value:
                return '{}'
            items = []
            for key, item in value.items():
                items.append(f"{next_pad}{json.dumps(str(key))}: {render(item, level + 1)}")
            return '{\n' + ',\n'.join(items) + '\n' + pad + '}'
        if isinstance(value, list):
            if not value:
                return '[]'
            items = [f"{next_pad}{render(item, level + 1)}" for item in value]
            return '[\n' + ',\n'.join(items) + '\n' + pad + ']'
        if isinstance(value, Decimal):
            return format(value, '.2f')
        return json.dumps(value)
    return render(obj, 0)


def main():
    with (ROOT / 'campaign_manifest.json').open() as f:
        manifest = json.load(f)
    crate_rows = load_csv('crate_cost.csv')
    billing_rows = load_csv('billing.csv')
    override_rows = load_csv('location_overrides.csv')
    suspension_rows = load_csv('suspensions.csv')

    crate_cost_by_tier = {row['crate_tier']: dec(row['crate_cost_usd']) for row in crate_rows}
    held_campaigns = {
        row['campaign_id'] for row in suspension_rows
        if row.get('suspension_status') == 'hold'
    }

    campaigns = []
    for campaign in flatten_campaigns(manifest):
        if campaign.get('analysis_flag') != 'review':
            continue
        if campaign.get('campaign_id') in held_campaigns:
            continue

        billing = latest_billing_by_campaign(campaign, billing_rows)
        payment = dec(billing['payment_per_dispatch_per_clinic_usd'])
        active_clinics = active_clinics_for_campaign(campaign, override_rows)
        crate_cost = crate_cost_by_tier[campaign['crate_tier']]

        six = metric_block(campaign, active_clinics, payment, crate_cost, SIX_DAY)
        twelve = metric_block(campaign, active_clinics, payment, crate_cost, TWELVE_DAY)
        diff = money(twelve['annual_margin_usd'] - six['annual_margin_usd'])

        campaigns.append({
            'campaign_id': campaign['campaign_id'],
            'campaign_name': campaign['campaign_name'],
            'matched_billing_label': billing['campaign_label'],
            'billing_cycle_tag': billing['cycle_tag'],
            'payment_per_dispatch_per_clinic_usd': money(payment),
            'active_clinics': active_clinics,
            'crate_tier': campaign['crate_tier'],
            'crate_cost_usd': money(crate_cost),
            'drug_cost_per_1000_doses_usd': money(dec(campaign['drug_cost_per_1000_doses_usd'])),
            'doses_per_day': int(campaign['doses_per_day']),
            'six_day': six,
            'twelve_day': twelve,
            'annual_margin_6_day_usd': six['annual_margin_usd'],
            'annual_margin_12_day_usd': twelve['annual_margin_usd'],
            'annual_margin_difference_12_minus_6_usd': diff,
        })

    campaigns.sort(key=lambda row: row['campaign_id'])

    total_6 = money(sum((row['annual_margin_6_day_usd'] for row in campaigns), Decimal('0')))
    total_12 = money(sum((row['annual_margin_12_day_usd'] for row in campaigns), Decimal('0')))
    total_diff = money(sum((row['annual_margin_difference_12_minus_6_usd'] for row in campaigns), Decimal('0')))
    abs_diff = money(abs(total_diff))

    decision = 'move_to_12_day' if abs_diff < THRESHOLD else 'keep_6_day'
    justification = (
        f"Absolute total margin difference is ${format(abs_diff, '.2f')}, "
        f"which is {'below' if abs_diff < THRESHOLD else 'at or above'} the $11,000 threshold; "
        f"therefore the recommendation is {decision}."
    )

    output = {
        'assumptions': {
            '6-day': {
                'days_per_dispatch': 6,
                'dispatches_per_year': 60,
            },
            '12-day': {
                'days_per_dispatch': 12,
                'dispatches_per_year': 30,
            },
            'annual_crate_cost_formula': 'crate_cost_usd * dispatches_per_year',
            'decision_threshold_usd': money(THRESHOLD),
        },
        'campaigns': campaigns,
        'totals': {
            'total_annual_margin_6_day_usd': total_6,
            'total_annual_margin_12_day_usd': total_12,
            'total_annual_margin_difference_12_minus_6_usd': total_diff,
            'absolute_total_margin_difference_usd': abs_diff,
        },
        'recommendation': {
            'decision': decision,
            'justification': justification,
        },
    }

    (ROOT / 'vaxcrate_analysis.json').write_text(json_number_dump(output, indent=2) + '\n')

    md_lines = [
        '# VaxCrate Dispatch Interval Summary',
        f"Total 6-day margin (USD): ${format(total_6, '.2f')}",
        f"Total 12-day margin (USD): ${format(total_12, '.2f')}",
        f"Absolute difference (USD): ${format(abs_diff, '.2f')}",
        f"Decision: {decision}",
        justification,
    ]
    (ROOT / 'vaxcrate_summary.md').write_text('\n'.join(md_lines) + '\n')


if __name__ == '__main__':
    main()
